const tg = window.Telegram?.WebApp;
// Theme belongs to this mini-app, never to Telegram's color scheme.
function applyAppTheme(){const theme=localStorage.getItem('student-diary-theme')||'dark';document.documentElement.dataset.theme=theme;document.documentElement.classList.toggle('dark-theme',theme==='dark');}
if (tg) { tg.ready(); tg.expand(); try { tg.setHeaderColor('#000000'); tg.setBackgroundColor('#000000'); } catch(e){} }
applyAppTheme();
window.toggleAppTheme=()=>{const next=(document.documentElement.dataset.theme==='dark'?'light':'dark');localStorage.setItem('student-diary-theme',next);applyAppTheme();renderMore();};

const pad=n=>String(n).padStart(2,'0');
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`};
const urlParams=new URLSearchParams(window.location.search);
const state={page:urlParams.get('admin')==='1'?'admin':'home',me:null,date:localToday(),discipline:null,expandedGrades:{},admin:false,scheduleLessons:[],settings:null,setup:false,hwCreateToken:null,adminHwTab:'active',week:1};
const content=document.getElementById('content'),title=document.getElementById('pageTitle'),toast=document.getElementById('toast'),initData=tg?.initData||'';
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const api=async(url,opts={})=>{opts.headers={...opts.headers,'X-Telegram-Init-Data':initData,'Content-Type':'application/json'};const r=await fetch(url,opts);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||'Ошибка запроса');return d};
function toastMsg(s){toast.textContent=s;toast.className='show';setTimeout(()=>toast.className='',2600)}
function stat(v,label){return `<div class="stat"><strong>${v??'—'}</strong><span>${label}</span></div>`}
function parseLocalDate(s){if(!s)return null;if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)}if(/^\d{2}\.\d{2}\.\d{4}$/.test(s)){const [d,m,y]=s.split('.').map(Number);return new Date(y,m-1,d,12)}return null}
function isoDate(d){return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function fmtDate(s){const d=parseLocalDate(s);return d?d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'}):'—'}
function fullDate(s){const d=parseLocalDate(s);return d?d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}):'—'}
function dayName(s){const d=parseLocalDate(s);return d?d.toLocaleDateString('ru-RU',{weekday:'long'}):'—'}
function gradeClass(v){return ['1','2','3','4','5'].includes(String(v))?`grade-${v}`:(v==='Н'?'grade-n':v==='Б'?'grade-b':v==='О'?'grade-o':v==='+'?'grade-plus':'')}
function gradeBadge(v){return v?`<span class="grade-badge ${gradeClass(v)}">${esc(v)}</span>`:'<span class="grade-empty">—</span>'}
function lessonHtml(x){return `<div class="lesson"><div><div class="time">${esc(x.start)}</div><div class="muted">${esc(x.end)}</div></div><div><b>${esc(x.emoji||'📚')} ${esc(x.discipline)}</b><div class="muted">${x.lesson_no} пара · ${esc(x.lesson_type||'')} · ${esc(x.room||'')}</div></div></div>`}
function hwHtml(x){return `<button class="hw hw-btn" onclick="openHomework(${x.id})"><div class="title">${esc(x.title||'Задание')}</div><div class="muted">${esc(x.emoji)} ${esc(x.discipline)}${x.due_date?' · до '+esc(fullDate(x.due_date)):''}</div><div class="muted hw-preview">${esc((x.text||'').slice(0,130))}</div></button>`}
function eventHtml(x){return `<div class="event"><b>${esc(x.title)}</b><div class="muted">${esc(x.description||'')}</div><div class="muted">${esc(x.created_at||'')}</div></div>`}
function loading(){content.innerHTML='<div class="loading">Загрузка…</div>'}
function setNav(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===(state.page==='homework'?'home':state.page==='settings'?'more':state.page))); const ab=document.getElementById('adminNavBtn');if(ab)ab.hidden=true;document.getElementById('bottomNav')?.classList.remove('admin-mode')}
async function render(){setNav();loading();try{if(state.page==='home')await renderHome();else if(state.page==='schedule')await renderSchedule();else if(state.page==='homework')await renderHomework();else if(state.page==='grades')await renderGrades();else if(state.page==='more')await renderMore();else if(state.page==='settings')await renderSettings();else if(state.page==='admin')await renderAdmin()}catch(e){content.innerHTML=`<div class="card"><h3>Не удалось загрузить</h3><p class="muted">${esc(e.message)}</p><button class="primary" onclick="render()">Повторить</button></div>`}}

async function renderHome(){
 title.textContent='Главная';const d=await api('/api/home');let books={items:[]};try{books=await api('/api/textbooks')}catch(e){}
 const profile=state.me||{};const lessonCard=(x,label,kind)=>x?`<div class="lesson-tile ${kind}"><div class="tile-label">${label}</div><div class="tile-time">${esc(x.start)} — ${esc(x.end)}</div><b>${esc(x.emoji||'📚')} ${esc(x.discipline)}</b><small>${esc(x.room||'Аудитория не указана')}</small><span class="tile-foot">${x.lesson_no?x.lesson_no+' пара':''}</span></div>`:`<div class="lesson-tile ${kind}"><div class="tile-label">${label}</div><b>Пар нет</b><small>Можно немного отдохнуть</small></div>`;
 const palette=['blue','green','purple','orange','pink','cyan'];
 content.innerHTML=`<button class="profile-banner" onclick="go('more')"><div class="avatar">${esc((profile.full_name||'С').trim().charAt(0).toUpperCase())}</div><div class="profile-copy"><b>${esc(profile.full_name||'Студент')}</b><span>Группа: Р 26-1</span><span>Системы радиосвязи, мобильной связи и телерадиовещания</span></div><span class="chevron">›</span></button>
 <div class="section-heading"><h2>Пары</h2><button class="text-action" onclick="go('schedule')">Расписание ›</button></div><div class="lesson-now-grid">${lessonCard(d.current_lesson,'СЕЙЧАС','blue')}${lessonCard(d.next_lesson,'СЛЕДУЮЩАЯ','green')}</div>
 <button class="feature-link" onclick="go('homework')"><span class="feature-icon">✎</span><span><b>Домашние задания</b><small>Посмотреть задания и ближайшие дедлайны</small></span><span class="chevron">›</span></button>
 <div class="section-heading"><h2>Учебники</h2><button class="text-action" onclick="renderTextbooks()">Все ›</button></div>
 <div class="book-grid">${(books.items||[]).slice(0,6).map((x,i)=>`<button class="book-card ${palette[i%palette.length]}" onclick="sendTextbook(${x.id})"><span class="book-icon">▤</span><span class="book-info"><b>${esc(x.discipline)}${/\(.*\)/.test(x.title)?'':' (учебник)'}</b><small>${esc(x.title)}</small><span class="book-action">Отправить в Telegram ↗</span></span></button>`).join('')||'<div class="empty-state">📚<b>Учебники появятся здесь</b><span>Пока учебники не добавлены</span></div>'}</div>
 <div class="mini-stats"><div><span>Средний балл</span><b>${d.stats.average??'—'}</b></div><div><span>Всего оценок</span><b>${d.stats.grade_count??0}</b></div><button onclick="go('grades')">Все оценки ›</button></div>`;
}
window.shiftDate=(n,cb)=>{const d=parseLocalDate(state.date)||new Date();d.setDate(d.getDate()+n);state.date=isoDate(d);if(typeof cb==='function')cb()}
window.openCalendar=(initial,onSelect)=>{const d=parseLocalDate(initial)||new Date();let month=new Date(d.getFullYear(),d.getMonth(),1,12);const root=document.getElementById('modalRoot');const draw=()=>{const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1,12),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate();let cells='';for(let i=0;i<offset;i++)cells+='<div></div>';for(let day=1;day<=days;day++){const value=`${y}-${pad(m+1)}-${pad(day)}`,active=value===initial?'active':'';cells+=`<button class="${active}" onclick="window.__pickDate('${value}')">${day}</button>`}root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="calendar-title"><button class="icon-btn" onclick="window.__calShift(-1)">‹</button><b>${month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</b><button class="icon-btn" onclick="window.__calShift(1)">›</button></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="cal-head">${x}</div>`).join('')}${cells}</div><div class="toolbar" style="margin-top:12px"><button class="secondary" onclick="window.__pickDate('${localToday()}')">Сегодня</button><button class="secondary" onclick="closeModal()">Отмена</button></div></div></div>`};window.__calShift=n=>{month.setMonth(month.getMonth()+n);draw()};window.__pickDate=value=>{closeModal();if(typeof onSelect==='function')onSelect(value)};draw()}
window.closeModal=()=>{document.getElementById('modalRoot').innerHTML=''}

async function renderSchedule(){title.textContent='Расписание';const selected=parseLocalDate(state.date)||new Date();const monday=new Date(selected);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));const weekStart=new Date(monday);const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);const d=await api('/api/schedule?day='+encodeURIComponent(state.date));const days=Array.from({length:7},(_,i)=>{const x=new Date(weekStart);x.setDate(weekStart.getDate()+i);return isoDate(x)});content.innerHTML=`<div class="week-control"><div><small>УЧЕБНАЯ НЕДЕЛЯ</small><b>${state.week} неделя</b></div><select aria-label="Выбрать неделю" onchange="const dt=parseLocalDate(state.date);dt.setDate(dt.getDate()+(Number(this.value)-state.week)*7);state.week=Number(this.value);state.date=isoDate(dt);renderSchedule()">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${state.week===i+1?'selected':''}>${i+1} неделя</option>`).join('')}</select><button class="icon-btn" onclick="openCalendar('${state.date}',dt=>{state.date=dt;renderSchedule()})">▦</button></div><div class="week-strip">${days.map(dt=>`<button class="day-chip ${dt===state.date?'selected':''}" onclick="state.date='${dt}';renderSchedule()"><span>${dayName(dt).slice(0,2)}</span><b>${parseLocalDate(dt).getDate()}</b><small>${fmtDate(dt)}</small></button>`).join('')}</div><div class="section-heading"><h2>${dayName(state.date)}, ${fullDate(state.date)}</h2><button class="text-action" onclick="openCalendar('${state.date}',dt=>{state.date=dt;renderSchedule()})">Выбрать дату</button></div><div class="schedule-list">${d.lessons.length?d.lessons.map((x,i)=>`<div class="schedule-card accent-${i%5}"><div class="schedule-number">${x.lesson_no||i+1}</div><div class="schedule-details"><span class="time">${esc(x.start)} — ${esc(x.end)}</span><b>${esc(x.emoji||'📚')} ${esc(x.discipline)}</b><small>${esc(x.lesson_type||'Занятие')} · ${esc(x.room||'Аудитория не указана')}</small></div><span class="chevron">›</span></div>`).join(''):'<div class="empty-state">☼<b>На этот день пар нет</b><span>Выберите другой день или неделю</span></div>'}</div>`}

async function renderHomework(){title.textContent='Домашнее задание';const d=await api('/api/homework');const groups={};d.items.forEach(x=>(groups[x.discipline]??=[]).push(x));content.innerHTML=`<div class="card hero"><div class="avg">${d.count}</div><div class="muted">активных заданий</div></div>${Object.entries(groups).map(([name,items])=>`<div class="card"><h3>${esc(name)}</h3>${items.map(hwHtml).join('')}</div>`).join('')||'<div class="card"><p class="muted">Активных заданий нет.</p></div>'}${state.admin?'<div class="card"><button class="primary" style="width:100%" onclick="openHomeworkCreate()">＋ Добавить ДЗ</button></div>':''}`}
window.openHomework=async id=>{const d=await api('/api/homework');const x=d.items.find(v=>v.id===id);if(!x)return;const media=(x.media||[]).map(m=>`<button class="material-btn" onclick="sendHomeworkMedia(${x.id},${m.id})">📤 ${esc(m.caption||m.kind||'Файл')}</button>`).join('');const mats=(x.discipline_materials||[]).map(m=>`<button class="material-btn" onclick="sendMaterial(${x.id},${m.id})">📤 ${esc(m.title||m.caption||'Материал')}</button>`).join('');document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal modal-scroll"><div class="row"><h3>${esc(x.emoji)} ${esc(x.title||'Задание')}</h3><button class="icon-btn" onclick="closeModal()">×</button></div><div class="pill">${esc(x.discipline)}${x.due_date?' · до '+fullDate(x.due_date):''}</div><div class="homework-text">${esc(x.text||'')}</div>${x.explanation?`<div class="explanation"><b>Пояснение</b><div>${esc(x.explanation)}</div></div>`:''}${media||mats?`<h4>Материалы</h4><div class="material-list">${media}${mats}</div>`:''}</div></div>`}
window.sendHomeworkMedia=async(hid,mid)=>{try{await api(`/api/homework/${hid}/media/${mid}`,{method:'POST'});toastMsg('Файл отправлен в Telegram')}catch(e){toastMsg(e.message)}}
window.sendMaterial=async(hid,mid)=>{try{await api(`/api/homework/${hid}/material/${mid}`,{method:'POST'});toastMsg('Материал отправлен в Telegram')}catch(e){toastMsg(e.message)}}

async function renderGrades(){title.textContent='Оценки';const d=await api('/api/grades');const m=state.me||{};content.innerHTML=`<div class="grade-overview"><div class="average-ring"><b>${m.stats?.average??'—'}</b><small>средний балл</small></div><div class="grade-summary"><div><span>Всего оценок</span><b>${m.stats?.grade_count??0}</b></div><div><span>Н/у пропуски</span><b>${m.stats?.n_count??0}</b></div><div><span>По болезни</span><b>${m.stats?.b_count??0}</b></div><div><span>Опоздания</span><b>${m.stats?.o_count??0}</b></div></div></div><div class="section-heading"><h2>Дисциплины</h2><span class="muted">Нажмите, чтобы раскрыть</span></div><div class="discipline-list">${d.items.map((x,i)=>`<section class="discipline-wrap"><button class="discipline" onclick="toggleGrade(${x.id})"><span class="emoji grade-subject-${i%6}">${esc(x.emoji||'▤')}</span><span class="name">${esc(x.name)}<small class="muted">${x.grade_count} оценок · средний ${x.average??'—'}</small></span><b>${x.average??'—'}</b><span class="expand-arrow ${state.expandedGrades[x.id]?'open':''}">⌄</span></button><div id="grades-${x.id}" class="inline-grades" ${state.expandedGrades[x.id]?'':'hidden'}></div></section>`).join('')||'<div class="empty-state">▥<b>Оценок пока нет</b></div>'}</div>`;for(const x of d.items.filter(v=>state.expandedGrades[v.id]))loadInlineGrades(x.id)}
window.toggleGrade=async id=>{state.expandedGrades[id]=!state.expandedGrades[id];const box=document.getElementById('grades-'+id);if(!box)return;if(state.expandedGrades[id]){box.hidden=false;box.innerHTML='<div class="muted">Загружаем оценки…</div>';await loadInlineGrades(id)}else box.hidden=true;const btn=box.parentElement.querySelector('.expand-arrow');btn?.classList.toggle('open',state.expandedGrades[id])};
async function loadInlineGrades(id){try{const x=await api('/api/grades/'+id);const box=document.getElementById('grades-'+id);if(!box)return;box.innerHTML=x.items.length?x.items.map(g=>`<div class="inline-grade-row"><span>${fullDate(g.grade_date)}</span><span>${esc(g.title||g.kind||'Оценка')}</span>${gradeBadge(g.value)}</div>`).join(''):'<div class="muted empty-grade">Оценок по предмету пока нет</div>'}catch(e){const box=document.getElementById('grades-'+id);if(box)box.innerHTML='<div class="muted">Не удалось загрузить оценки</div>'}}

async function renderTextbooks(){title.textContent='Учебники';const d=await api('/api/textbooks');const groups={};d.items.forEach(x=>(groups[x.discipline]??=[]).push(x));content.innerHTML=`<div class="card"><div class="notice">Нажмите на учебник — бот отправит его прямо в Telegram.</div></div>${Object.entries(groups).map(([name,items])=>`<div class="card"><h3>${esc(items[0].emoji)} ${esc(name)}</h3>${items.map(x=>`<button class="material-btn" onclick="sendTextbook(${x.id})">📘 ${esc(x.title)}</button>`).join('')}</div>`).join('')||'<div class="card"><p class="muted">Учебников пока нет.</p></div>'}`}
window.sendTextbook=async id=>{try{await api(`/api/textbooks/${id}/send`,{method:'POST'});toastMsg('Учебник отправлен в Telegram');try{tg?.HapticFeedback?.notificationOccurred('success')}catch(e){}}catch(e){toastMsg(e.message)}}

async function renderMore(){title.textContent='Личный кабинет';const m=state.me||await api('/api/me');state.me=m;const d=await api('/api/grades');let s=state.settings;try{s=s||await api('/api/settings');state.settings=s}catch(e){s={}}const opts=[5,10,15,30,45,60,90];const theme=document.documentElement.dataset.theme||'dark';content.innerHTML=`<div class="account-card"><div class="avatar avatar-large">${esc((m.full_name||'С').trim().charAt(0).toUpperCase())}</div><div class="profile-copy"><b>${esc(m.full_name||'Студент')}</b><span>Группа: Р 26-1</span><span>Специальность: Системы радиосвязи, мобильной связи и телерадиовещания</span></div></div><div class="mini-stats account-average"><div><span>Средний балл</span><b>${m.stats.average??'—'}</b></div><div><span>Оценок</span><b>${m.stats.grade_count??0}</b></div><div><span>Пропусков</span><b>${(m.stats.n_count||0)+(m.stats.b_count||0)}</b></div></div><div class="section-heading"><h2>Настройки</h2></div><div class="settings-panel"><div class="setting-row"><span>◐ <b>Тёмная тема</b></span><label class="switch"><input id="themeSwitch" type="checkbox" ${theme==='dark'?'checked':''} onchange="toggleAppTheme()"><i></i></label></div><div class="setting-row"><span>♧ <b>Уведомления</b></span><label class="switch"><input id="masterNotify" type="checkbox" ${['next_lesson','tomorrow_schedule','deadline_reminders','new_homework','updates','other'].some(k=>s[k])?'checked':''} onchange="toggleAllNotifications(this.checked)"><i></i></label></div><div class="settings-subtitle">ТИПЫ УВЕДОМЛЕНИЙ</div>${[['setNext','next_lesson','О следующей паре'],['setTomorrow','tomorrow_schedule','О расписании на завтра'],['setDeadline','deadline_reminders','О дедлайне'],['setHw','new_homework','Новое ДЗ'],['setUpdates','updates','Обновления'],['setOther','other','Прочие уведомления']].map(([id,key,label])=>`<div class="setting-row setting-child"><span>${label}</span><label class="switch"><input id="${id}" data-setting="${key}" type="checkbox" ${s[key]?'checked':''} onchange="saveInlineSettings()"><i></i></label></div>`).join('')}<div class="setting-select"><label for="setMinutes">Напоминать о следующей паре за</label><select id="setMinutes" onchange="saveInlineSettings()">${opts.map(x=>`<option value="${x}" ${Number(s.next_lesson_minutes)===x?'selected':''}>За ${x} минут</option>`).join('')}</select></div><div class="setting-row setting-child"><span>Тихие уведомления</span><label class="switch"><input id="setSilent" data-setting="silent_notifications" type="checkbox" ${s.silent_notifications?'checked':''} onchange="saveInlineSettings()"><i></i></label></div></div><div class="section-heading"><h2>Средние по дисциплинам</h2><button class="text-action" onclick="go('grades')">Все оценки ›</button></div><div class="settings-panel">${d.items.map(x=>`<div class="avg-line"><span>${esc(x.emoji||'▤')} ${esc(x.name)}</span><b>${x.average??'—'}</b></div>`).join('')||'<p class="muted">Нет оценок.</p>'}</div><div class="toolbar profile-actions"><button class="secondary" onclick="renderTextbooks()">▤ Учебники</button><button class="secondary" onclick="showEvents()">♧ События</button>${m.is_admin?'<button class="primary" onclick="go(\'admin\')">⚙ Админ-панель</button>':''}</div>`}
window.toggleAllNotifications=checked=>{document.querySelectorAll('[data-setting]').forEach(el=>{if(el.id!=='setSilent')el.checked=checked});saveInlineSettings()};
window.saveInlineSettings=async()=>{try{const payload={tomorrow_schedule:document.getElementById('setTomorrow').checked,next_lesson:document.getElementById('setNext').checked,updates:document.getElementById('setUpdates').checked,other:document.getElementById('setOther').checked,deadline_reminders:document.getElementById('setDeadline').checked,next_lesson_minutes:Number(document.getElementById('setMinutes').value),new_homework:document.getElementById('setHw').checked,setup_done:true,setup_version:1,silent_notifications:document.getElementById('setSilent').checked};await api('/api/settings',{method:'PATCH',body:JSON.stringify(payload)});state.settings=payload;toastMsg('Настройки сохранены')}catch(e){toastMsg(e.message)}};

async function showEvents(){title.textContent='События';const d=await api('/api/events');content.innerHTML=`<div class="card"><button class="secondary" onclick="go('more')">← Назад</button>${d.items.map(eventHtml).join('')||'<p class="muted">Событий нет.</p>'}</div>`}

async function renderSettings(){title.textContent=state.setup?'Первоначальная настройка':'Настройки';const s=state.settings||await api('/api/settings');state.settings=s;const opts=[5,10,15,30,45,60,90];content.innerHTML=`<div class="card ${state.setup?'hero':''}"><h2>${state.setup?'⚙️ Полная первоначальная настройка':'⚙️ Настройки'}</h2><p class="muted">Здесь сохраняются ваши персональные настройки бота. Их можно изменить в любой момент.</p></div><div class="card"><h3>🔔 Уведомления</h3><label class="check-all"><input id="setNext" type="checkbox" ${s.next_lesson?'checked':''}> Следующая пара</label><label class="check-all"><input id="setTomorrow" type="checkbox" ${s.tomorrow_schedule?'checked':''}> Расписание на завтра</label><label class="check-all"><input id="setDeadline" type="checkbox" ${s.deadline_reminders?'checked':''}> Напоминания о дедлайнах</label><label class="check-all"><input id="setHw" type="checkbox" ${s.new_homework?'checked':''}> Новое ДЗ</label><label class="check-all"><input id="setUpdates" type="checkbox" ${s.updates?'checked':''}> Обновления</label><label class="check-all"><input id="setOther" type="checkbox" ${s.other?'checked':''}> Прочие уведомления</label><label class="check-all"><input id="setSilent" type="checkbox" ${s.silent_notifications?'checked':''}> 🔕 Тихие уведомления</label><div class="field"><label>Напоминать о следующей паре за</label><select id="setMinutes">${opts.map(x=>`<option value="${x}" ${Number(s.next_lesson_minutes)===x?'selected':''}>${x} мин.</option>`).join('')}</select></div><p class="muted">Важные системные сообщения отключить нельзя.</p><button class="primary" style="width:100%" onclick="saveSettings()">${state.setup?'✅ Сохранить и завершить настройку':'💾 Сохранить'}</button></div>`}
window.saveSettings=async()=>{try{const payload={tomorrow_schedule:document.getElementById('setTomorrow').checked,next_lesson:document.getElementById('setNext').checked,updates:document.getElementById('setUpdates').checked,other:document.getElementById('setOther').checked,deadline_reminders:document.getElementById('setDeadline').checked,next_lesson_minutes:Number(document.getElementById('setMinutes').value),new_homework:document.getElementById('setHw').checked,setup_done:true,setup_version:1,silent_notifications:document.getElementById('setSilent').checked};await api('/api/settings',{method:'PATCH',body:JSON.stringify(payload)});state.setup=false;state.settings=await api('/api/settings');state.me=await api('/api/me');toastMsg('Настройки сохранены');go('more')}catch(e){toastMsg(e.message)}}

