async function adminEvents(){title.textContent='События для администратора';const d=await api('/api/admin/events');content.innerHTML=`<div class="card"><button class="secondary" onclick="go('admin')">← Назад</button>${d.items.map(x=>`<div class="event"><b>${esc(x.full_name)}</b> · ${esc(x.emoji||'')} ${esc(x.discipline||'')}</div><div class="muted">${esc(x.title)} — ${esc(x.description||'')}</div><div class="muted">${esc(x.created_at||'')}</div>`).join('')||'<p class="muted">Событий нет.</p>'}</div>`}

window.openHomeworkCreate=async()=>{state.hwCreateToken=(window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`);const ds=await api('/api/admin/disciplines');document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal modal-scroll"><div class="row"><h3>＋ Новое ДЗ</h3><button class="icon-btn" onclick="closeModal()">×</button></div><div class="field"><label>Дисциплина</label><select id="hwDisc">${ds.items.map(x=>`<option value="${x.id}">${esc(x.emoji)} ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Название</label><input id="hwTitle" placeholder="Например: Задание №3"></div><div class="field"><label>Текст задания</label><textarea id="hwText" placeholder="Текст домашнего задания"></textarea></div><div class="field"><label>Дата сдачи</label><input id="hwDue" type="date" value="${state.date}"></div><div class="field"><label>Пояснение</label><textarea id="hwExpl" placeholder="Можно оставить пустым"></textarea></div><label class="check-all"><input id="hwFile" type="checkbox"> После создания я отправлю файл этому боту</label><button class="primary" style="width:100%;margin-top:10px" onclick="createHomeworkFromMiniApp()">Создать ДЗ</button></div></div>`}
window.createHomeworkFromMiniApp=async()=>{const btn=document.querySelector('#modalRoot .primary');if(btn?.dataset.busy==='1')return;const payload={discipline_id:Number(document.getElementById('hwDisc').value),title:document.getElementById('hwTitle').value.trim(),text:document.getElementById('hwText').value.trim(),due_date:document.getElementById('hwDue').value,explanation:document.getElementById('hwExpl').value.trim(),wants_file:document.getElementById('hwFile').checked,client_token:state.hwCreateToken};if(!payload.title||!payload.text||!payload.due_date){toastMsg('Заполните название, текст и дату');return}try{if(btn){btn.dataset.busy='1';btn.disabled=true;btn.textContent='Создание…'}const r=await api('/api/homework',{method:'POST',body:JSON.stringify(payload)});closeModal();toastMsg(r.duplicate?'ДЗ уже создано — повторное создание отменено':(r.waiting_for_file?'ДЗ создано. Отправьте файл боту':'ДЗ создано'));renderHomework()}catch(e){toastMsg(e.message)}}

async function adminSchedule(){title.textContent='Расписание';const d=await api('/api/admin/schedule/'+state.date);const ds=await api('/api/admin/disciplines');state.scheduleLessons=d.lessons;content.innerHTML=`<div class="card"><div class="date-actions"><button class="secondary" onclick="shiftDate(-1,()=>adminSchedule())">‹</button><button class="date-main" onclick="openCalendar('${state.date}',dt=>{state.date=dt;adminSchedule()})">📅 ${fmtDate(state.date)}<span>${esc(dayName(state.date))}</span></button><button class="secondary" onclick="shiftDate(1,()=>adminSchedule())">›</button></div><div class="schedule-day">${esc(dayName(state.date))}</div></div><div class="card"><div id="lessonList">${d.lessons.map(x=>`<div class="lesson admin-lesson"><div class="lesson-no"><span class="badge">${x.lesson_no}</span></div><div><div class="lesson-time-title"><span class="time">${esc(x.start)}–${esc(x.end)}</span><b>${esc(x.emoji)} ${esc(x.discipline)}</b></div><div class="muted">${esc(x.lesson_type||'')} · ${esc(x.room||'')}</div><div class="toolbar" style="margin-top:7px"><button class="secondary" onclick="editLesson(${x.id})">Изменить</button><button class="secondary danger" onclick="deleteLesson(${x.id})">Удалить</button></div></div></div>`).join('')||'<p class="muted">Пар нет.</p>'}</div><button class="primary" onclick='addLessonPrompt(${JSON.stringify(ds.items)})'>＋ Добавить пару</button></div>`}
window.editLesson=async id=>{const d=await api('/api/admin/schedule/'+state.date);const x=d.lessons.find(v=>v.id===id);const ds=await api('/api/admin/disciplines');if(!x)return;content.innerHTML=`<div class="card"><button class="secondary" onclick="adminSchedule()">← Назад</button><h2 style="margin-top:12px">Редактировать пару</h2><div class="form-row"><div class="field"><label>Номер пары</label><input id="elNo" type="number" min="1" max="20" value="${x.lesson_no}"></div><div class="field"><label>Аудитория</label><input id="elRoom" value="${esc(x.room||'')}"></div></div><div class="form-row"><div class="field"><label>Начало</label><input id="elStart" type="time" value="${x.start}"></div><div class="field"><label>Конец</label><input id="elEnd" type="time" value="${x.end}"></div></div><div class="field"><label>Дисциплина</label><select id="elDisc">${ds.items.map(v=>`<option value="${v.id}" ${v.id===x.discipline_id?'selected':''}>${esc(v.emoji)} ${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Тип пары</label><select id="elType">${['ПР','ЛЕК','ЛАБ'].map(v=>`<option ${v===x.lesson_type?'selected':''}>${v}</option>`).join('')}</select></div><button class="primary" onclick="saveLesson(${id})">Сохранить</button></div>`}
window.saveLesson=async id=>{try{await api('/api/admin/schedule/lesson/'+id,{method:'PATCH',body:JSON.stringify({lesson_no:Number(document.getElementById('elNo').value),start:document.getElementById('elStart').value,end:document.getElementById('elEnd').value,discipline_id:Number(document.getElementById('elDisc').value),lesson_type:document.getElementById('elType').value,room:document.getElementById('elRoom').value})});toastMsg('Сохранено');adminSchedule()}catch(e){toastMsg(e.message)}}
window.deleteLesson=async id=>{if(!confirm('Удалить пару?'))return;try{await api('/api/admin/schedule/lesson/'+id,{method:'DELETE'});adminSchedule()}catch(e){toastMsg(e.message)}}
window.addLessonPrompt=async ds=>{document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="row"><h3>＋ Добавить пару</h3><button class="icon-btn" onclick="closeModal()">×</button></div><div class="form-row"><div class="field"><label>Номер пары</label><input id="alNo" type="number" min="1" max="20" value="1"></div><div class="field"><label>Аудитория</label><input id="alRoom"></div></div><div class="form-row"><div class="field"><label>Начало</label><input id="alStart" type="time" value="08:30"></div><div class="field"><label>Конец</label><input id="alEnd" type="time" value="10:00"></div></div><div class="field"><label>Дисциплина</label><select id="alDisc">${ds.map(v=>`<option value="${v.id}">${esc(v.emoji)} ${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Тип пары</label><select id="alType"><option>ПР</option><option>ЛЕК</option><option>ЛАБ</option></select></div><button class="primary" style="width:100%" onclick="saveNewLesson()">Добавить</button></div></div>`}
window.saveNewLesson=async()=>{try{await api('/api/admin/schedule/lesson',{method:'POST',body:JSON.stringify({day:state.date,lesson_no:Number(document.getElementById('alNo').value),start:document.getElementById('alStart').value,end:document.getElementById('alEnd').value,discipline_id:Number(document.getElementById('alDisc').value),room:document.getElementById('alRoom').value,lesson_type:document.getElementById('alType').value})});closeModal();toastMsg('Пара добавлена');adminSchedule()}catch(e){toastMsg(e.message)}}


function adminBack(){go('admin')}
async function adminHomework(){
  title.textContent='Управление ДЗ';
  api('/api/admin/homework').then(d=>{
    const active=d.items.filter(x=>!x.archived);
    const archived=d.items.filter(x=>x.archived);
    const items=state.adminHwTab==='archive'?archived:active;
    content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><button class="primary" style="width:100%;margin-top:10px" onclick="openHomeworkCreate()">＋ Новое ДЗ</button></div>
      <div class="card"><div class="toolbar"><button class="${state.adminHwTab==='active'?'primary':'secondary'}" onclick="state.adminHwTab='active';adminHomework()">📝 Активные (${active.length})</button><button class="${state.adminHwTab==='archive'?'primary':'secondary'}" onclick="state.adminHwTab='archive';adminHomework()">📦 Архив (${archived.length})</button></div></div>
      ${items.map(x=>`<div class="card"><div class="row"><div><h3>${esc(x.emoji)} ${esc(x.title)}</h3><div class="muted">${esc(x.discipline)} · до ${esc(fullDate(x.due_date))}</div></div></div><div class="toolbar" style="margin-top:9px"><button class="secondary" onclick="openAdminHomework(${x.id})">Открыть</button>${x.archived?`<button class="secondary" onclick="restoreHomework(${x.id})">♻️ Вернуть</button>`:`<button class="secondary" onclick="archiveHomework(${x.id})">📦 В архив</button>`}<button class="secondary danger" onclick="deleteAdminHomework(${x.id})">🗑 Удалить</button></div></div>`).join('')||'<div class="card"><p class="muted">В этом разделе ДЗ нет.</p></div>'}`;
  }).catch(e=>{content.innerHTML=`<div class="card"><p>${esc(e.message)}</p><button class="secondary" onclick="adminHomework()">Повторить</button></div>`})
}
window.adminHomework=adminHomework;
window.archiveHomework=async id=>{if(!confirm('Отправить ДЗ в архив?'))return;try{await api('/api/admin/homework/'+id+'/archive',{method:'POST'});adminHomework()}catch(e){toastMsg(e.message)}};
window.restoreHomework=async id=>{try{await api('/api/admin/homework/'+id+'/restore',{method:'POST'});adminHomework()}catch(e){toastMsg(e.message)}};
window.deleteAdminHomework=async id=>{if(!confirm('Удалить ДЗ безвозвратно?'))return;try{await api('/api/admin/homework/'+id,{method:'DELETE'});adminHomework()}catch(e){toastMsg(e.message)}};
window.openAdminHomework=async id=>{try{const d=await api('/api/admin/homework/'+id);const x=d.item;const media=(d.media||[]).map(m=>`<div class="material-btn row"><span>📎 ${esc(m.caption||m.kind||'Файл')}</span><button class="secondary danger" onclick="deleteHomeworkMedia(${m.id},${x.id})">Удалить</button></div>`).join('');const a=d.answer||{};content.innerHTML=`<div class="card"><button class="secondary" onclick="adminHomework()">← Назад</button><div class="pill" style="margin-top:12px">${esc(x.discipline)}${x.due_date?' · до '+fullDate(x.due_date):''}</div><div class="field"><label>Название ДЗ</label><input id="ehTitle" value="${esc(x.title||'')}"></div><div class="field"><label>Текст задания</label><textarea id="ehText" rows="7">${esc(x.text||'')}</textarea></div><div class="field"><label>Пояснение</label><textarea id="ehExpl" rows="4">${esc(x.explanation||'')}</textarea></div><div class="field"><label>Дата сдачи</label><input id="ehDue" type="date" value="${isoDateFromRu(x.due_date)}"></div><div class="field"><label>Готовый ответ (текст)</label><textarea id="ehAnswer" rows="5" placeholder="Если готовый ответ текстовый">${esc(a.text||'')}</textarea></div><button class="primary" style="width:100%" onclick="saveAdminHomework(${x.id})">💾 Сохранить изменения</button></div><div class="card"><h3>📎 Файлы ДЗ</h3>${media||'<p class="muted">Файлов нет.</p>'}<button class="secondary" style="width:100%;margin-top:10px" onclick="requestHomeworkFile(${x.id})">📎 ${d.media&&d.media.length?'Добавить ещё файл':'Добавить файл'} через бота</button></div><div class="card"><h3>💡 Готовый ответ</h3><p class="muted">${a.file_id?`Прикреплён файл: ${esc(a.kind||'файл')}`:'Файла готового ответа нет.'}</p><div class="toolbar"><button class="secondary" onclick="requestHomeworkAnswerFile(${x.id})">📎 ${a.file_id?'Заменить файл':'Добавить файл'}</button>${a.file_id||a.text?`<button class="secondary danger" onclick="deleteHomeworkAnswer(${x.id})">🗑 Удалить ответ</button>`:''}</div></div><div class="card"><div class="toolbar">${x.archived?`<button class="secondary" onclick="restoreHomework(${x.id})">♻️ Вернуть из архива</button>`:`<button class="secondary" onclick="archiveHomework(${x.id})">📦 В архив</button>`}<button class="secondary danger" onclick="deleteAdminHomework(${x.id})">🗑 Удалить ДЗ</button></div></div>`}catch(e){toastMsg(e.message)}};
window.isoDateFromRu=v=>{if(!v)return '';const p=String(v).split('.');return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:v};
window.saveAdminHomework=async id=>{const payload={title:document.getElementById('ehTitle').value.trim(),text:document.getElementById('ehText').value,explanation:document.getElementById('ehExpl').value,due_date:document.getElementById('ehDue').value,answer_text:document.getElementById('ehAnswer').value};if(!payload.title||!payload.text||!payload.due_date)return toastMsg('Заполните название, текст и дату');try{await api('/api/admin/homework/'+id,{method:'PATCH',body:JSON.stringify(payload)});toastMsg('ДЗ сохранено');openAdminHomework(id)}catch(e){toastMsg(e.message)}};
window.requestHomeworkFile=async id=>{try{await api('/api/admin/homework/'+id+'/request-file',{method:'POST'});toastMsg('Бот ждёт файл. Отправьте файл следующим сообщением в Telegram.')}catch(e){toastMsg(e.message)}};
window.deleteHomeworkMedia=async(mid,hid)=>{if(!confirm('Удалить файл ДЗ?'))return;try{await api('/api/admin/homework/'+hid+'/media/'+mid,{method:'DELETE'});openAdminHomework(hid)}catch(e){toastMsg(e.message)}};
window.requestHomeworkAnswerFile=async id=>{try{await api('/api/admin/homework/'+id+'/request-answer-file',{method:'POST'});toastMsg('Бот ждёт файл готового ответа. Отправьте его следующим сообщением в Telegram.')}catch(e){toastMsg(e.message)}};
window.deleteHomeworkAnswer=async id=>{if(!confirm('Удалить готовый ответ?'))return;try{await api('/api/admin/homework/'+id+'/answer',{method:'DELETE'});openAdminHomework(id)}catch(e){toastMsg(e.message)}};

