window.editAdminBookForm=async id=>{const [b,ds]=await Promise.all([api('/api/admin/textbooks'),api('/api/admin/disciplines')]);const x=b.items.find(v=>v.id===id);if(!x)return;content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBooks()">← Назад</button><h2 style="margin-top:12px">Редактировать учебник</h2><div class="field"><label>Дисциплина</label><select id="bookDisc">${ds.items.map(v=>`<option value="${v.id}" ${v.id===x.discipline_id?'selected':''}>${esc(v.emoji)} ${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Название</label><input id="bookTitle" value="${esc(x.title)}"></div><button class="primary" onclick="saveAdminBook(${id})">Сохранить</button></div>`};
window.saveAdminBook=async id=>{const titleValue=document.getElementById('bookTitle')?.value.trim();const discipline_id=Number(document.getElementById('bookDisc')?.value);if(!titleValue||!discipline_id)return toastMsg('Заполните поля');try{await api('/api/admin/textbooks/'+id,{method:'PATCH',body:JSON.stringify({discipline_id,title:titleValue})});toastMsg('Сохранено');adminBooks()}catch(e){toastMsg(e.message)}};
window.requestBookFile=async id=>{try{await api('/api/admin/textbooks/'+id+'/request-file',{method:'POST'});toastMsg('Бот ждёт файл. Отправьте его следующим сообщением в Telegram.')}catch(e){toastMsg(e.message)}};
window.deleteAdminBook=async id=>{if(!confirm('Удалить учебник?'))return;try{await api('/api/admin/textbooks/'+id,{method:'DELETE'});adminBooks()}catch(e){toastMsg(e.message)}};

async function adminMaterials(){
  title.textContent='Дополнительные материалы';
  try{const d=await api('/api/admin/materials');content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><button class="primary" style="width:100%;margin-top:10px" onclick="newAdminMaterialForm()">＋ Добавить материал</button></div>${d.items.map(x=>`<div class="card"><h3>📎 ${esc(x.title)}</h3><div class="muted">${esc(x.discipline)} · ${x.file_id?'📎 файл есть':'⚠️ файла нет'}</div><div class="toolbar" style="margin-top:9px"><button class="secondary" onclick="editAdminMaterialForm(${x.id})">✏️ Изменить</button><button class="secondary" onclick="requestMaterialFile(${x.id})">📎 ${x.file_id?'Поменять файл':'Добавить файл'}</button><button class="secondary danger" onclick="deleteAdminMaterial(${x.id})">🗑 Удалить</button></div></div>`).join('')||'<div class="card"><p class="muted">Материалов нет.</p></div>'}`}catch(e){content.innerHTML=`<div class="card"><p>${esc(e.message)}</p><button class="secondary" onclick="adminMaterials()">Повторить</button></div>`}}
window.adminMaterials=adminMaterials;
window.newAdminMaterialForm=async()=>{const ds=await api('/api/admin/disciplines');content.innerHTML=`<div class="card"><button class="secondary" onclick="adminMaterials()">← Назад</button><h2 style="margin-top:12px">Новый материал</h2><div class="field"><label>Дисциплина</label><select id="matDisc">${ds.items.map(x=>`<option value="${x.id}">${esc(x.emoji)} ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Название</label><input id="matTitle" placeholder="Название материала"></div><button class="primary" onclick="saveNewAdminMaterial()">Создать материал</button></div>`};
window.saveNewAdminMaterial=async()=>{const titleValue=document.getElementById('matTitle')?.value.trim();const discipline_id=Number(document.getElementById('matDisc')?.value);if(!titleValue||!discipline_id)return toastMsg('Заполните поля');try{await api('/api/admin/materials',{method:'POST',body:JSON.stringify({discipline_id,title:titleValue})});toastMsg('Материал добавлен');adminMaterials()}catch(e){toastMsg(e.message)}};
window.editAdminMaterialForm=async id=>{const [d,ds]=await Promise.all([api('/api/admin/materials'),api('/api/admin/disciplines')]);const x=d.items.find(v=>v.id===id);if(!x)return;content.innerHTML=`<div class="card"><button class="secondary" onclick="adminMaterials()">← Назад</button><h2 style="margin-top:12px">Редактировать материал</h2><div class="field"><label>Дисциплина</label><select id="matDisc">${ds.items.map(v=>`<option value="${v.id}" ${v.id===x.discipline_id?'selected':''}>${esc(v.emoji)} ${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Название</label><input id="matTitle" value="${esc(x.title)}"></div><button class="primary" onclick="saveAdminMaterial(${id})">Сохранить</button></div>`};
window.saveAdminMaterial=async id=>{const titleValue=document.getElementById('matTitle')?.value.trim();const discipline_id=Number(document.getElementById('matDisc')?.value);if(!titleValue||!discipline_id)return toastMsg('Заполните поля');try{await api('/api/admin/materials/'+id,{method:'PATCH',body:JSON.stringify({discipline_id,title:titleValue})});toastMsg('Сохранено');adminMaterials()}catch(e){toastMsg(e.message)}};
window.requestMaterialFile=async id=>{try{await api('/api/admin/materials/'+id+'/request-file',{method:'POST'});toastMsg('Бот ждёт файл. Отправьте его следующим сообщением в Telegram.')}catch(e){toastMsg(e.message)}};
window.deleteAdminMaterial=async id=>{if(!confirm('Удалить материал?'))return;try{await api('/api/admin/materials/'+id,{method:'DELETE'});adminMaterials()}catch(e){toastMsg(e.message)}};

async function adminStudents(){title.textContent='Студенты';try{const d=await api('/api/admin/students');content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><button class="primary" style="width:100%;margin-top:10px" onclick="newAdminStudentForm()">＋ Добавить студента</button></div>${d.items.map(x=>`<div class="card"><div class="row"><div><h3>👤 ${esc(x.full_name)}</h3><div class="muted">${x.telegram_id?'🟢 авторизован · '+x.telegram_id:'⚪ не авторизован'}</div></div><button class="secondary danger" onclick="deleteAdminStudent(${x.id})">🗑 Удалить</button></div></div>`).join('')||'<div class="card"><p class="muted">Студентов нет.</p></div>'}`}catch(e){content.innerHTML=`<div class="card"><p>${esc(e.message)}</p><button class="secondary" onclick="adminStudents()">Повторить</button></div>`}}
window.adminStudents=adminStudents;
window.newAdminStudentForm=()=>{content.innerHTML=`<div class="card"><button class="secondary" onclick="adminStudents()">← Назад</button><h2 style="margin-top:12px">Новый студент</h2><div class="field"><label>ФИО</label><input id="studentName" placeholder="Иванов Иван Иванович"></div><button class="primary" onclick="saveNewAdminStudent()">Добавить</button></div>`};
window.saveNewAdminStudent=async()=>{const n=document.getElementById('studentName')?.value.trim();if(!n)return toastMsg('Введите ФИО');try{await api('/api/admin/students',{method:'POST',body:JSON.stringify({full_name:n})});toastMsg('Студент добавлен');adminStudents()}catch(e){toastMsg(e.message)}};
window.deleteAdminStudent=async id=>{if(!confirm('Удалить студента безвозвратно?'))return;try{await api('/api/admin/students/'+id,{method:'DELETE'});adminStudents()}catch(e){toastMsg(e.message)}};

async function adminVip(){title.textContent='VIP';try{const d=await api('/api/admin/vip');content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><p class="muted" style="margin-top:10px">Нажмите кнопку рядом со студентом, чтобы выдать или снять VIP.</p></div>${d.items.map(x=>`<div class="card"><div class="row"><div><b>${esc(x.full_name)}</b><div class="muted">${esc(String(x.telegram_id))}</div></div><button class="${x.is_vip?'primary':'secondary'}" onclick="toggleAdminVip(${x.telegram_id})">${x.is_vip?'⭐ Снять VIP':'⭐ Выдать VIP'}</button></div></div>`).join('')||'<div class="card"><p class="muted">Нет авторизованных студентов.</p></div>'}`}catch(e){content.innerHTML=`<div class="card"><p>${esc(e.message)}</p><button class="secondary" onclick="adminVip()">Повторить</button></div>`}}
window.adminVip=adminVip;window.toggleAdminVip=async id=>{try{await api('/api/admin/vip/'+id+'/toggle',{method:'POST'});adminVip()}catch(e){toastMsg(e.message)}};

async function adminDisciplines(){title.textContent='Дисциплины';try{const d=await api('/api/admin/disciplines');content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><button class="primary" style="width:100%;margin-top:10px" onclick="newAdminDisciplineForm()">＋ Добавить дисциплину</button></div>${d.items.map(x=>`<div class="card"><div class="row"><div><h3>${esc(x.emoji)} ${esc(x.name)}</h3></div><div class="toolbar"><button class="secondary" onclick="editAdminDisciplineForm(${x.id})">✏️ Изменить</button><button class="secondary danger" onclick="deleteAdminDiscipline(${x.id})">🗑</button></div></div></div>`).join('')||'<div class="card"><p class="muted">Дисциплин нет.</p></div>'}`}catch(e){content.innerHTML=`<div class="card"><p>${esc(e.message)}</p><button class="secondary" onclick="adminDisciplines()">Повторить</button></div>`}}
window.adminDisciplines=adminDisciplines;
window.newAdminDisciplineForm=()=>{content.innerHTML=`<div class="card"><button class="secondary" onclick="adminDisciplines()">← Назад</button><h2 style="margin-top:12px">Новая дисциплина</h2><div class="field"><label>Название</label><input id="discName" placeholder="Название дисциплины"></div><div class="field"><label>Эмодзи</label><input id="discEmoji" value="📚"></div><button class="primary" onclick="saveNewAdminDiscipline()">Добавить</button></div>`};
window.saveNewAdminDiscipline=async()=>{const name=document.getElementById('discName')?.value.trim();const emoji=document.getElementById('discEmoji')?.value.trim()||'📚';if(!name)return toastMsg('Введите название');try{await api('/api/admin/disciplines',{method:'POST',body:JSON.stringify({name,emoji})});toastMsg('Дисциплина добавлена');adminDisciplines()}catch(e){toastMsg(e.message)}};
window.editAdminDisciplineForm=async id=>{const d=await api('/api/admin/disciplines');const x=d.items.find(v=>v.id===id);if(!x)return;content.innerHTML=`<div class="card"><button class="secondary" onclick="adminDisciplines()">← Назад</button><h2 style="margin-top:12px">Редактировать дисциплину</h2><div class="field"><label>Название</label><input id="discName" value="${esc(x.name)}"></div><div class="field"><label>Эмодзи</label><input id="discEmoji" value="${esc(x.emoji||'📚')}"></div><button class="primary" onclick="saveAdminDiscipline(${id})">Сохранить</button></div>`};
window.saveAdminDiscipline=async id=>{const name=document.getElementById('discName')?.value.trim();const emoji=document.getElementById('discEmoji')?.value.trim()||'📚';if(!name)return toastMsg('Введите название');try{await api('/api/admin/disciplines/'+id,{method:'PATCH',body:JSON.stringify({name,emoji})});toastMsg('Сохранено');adminDisciplines()}catch(e){toastMsg(e.message)}};
window.deleteAdminDiscipline=async id=>{if(!confirm('Скрыть дисциплину?'))return;try{await api('/api/admin/disciplines/'+id,{method:'DELETE'});adminDisciplines()}catch(e){toastMsg(e.message)}};

async function adminBroadcast(){title.textContent='Уведомление всем';content.innerHTML=`<div class="card"><button class="secondary" onclick="adminBack()">← Админ-панель</button><h3 style="margin-top:12px">📢 Отправить уведомление</h3><div class="field"><label>Тип</label><select id="bcKind"><option value="important">🚨 Важная информация — всем авторизованным</option><option value="update">🔄 Обновление — по настройкам</option><option value="other">📢 Прочее — по настройкам</option></select></div><div class="field"><label>Текст</label><textarea id="bcText" rows="7" placeholder="Текст уведомления"></textarea></div><button class="primary" style="width:100%" onclick="sendAdminBroadcast()">📤 Отправить</button></div>`}
window.sendAdminBroadcast=async()=>{const text=document.getElementById('bcText').value.trim();if(!text)return toastMsg('Введите текст');try{const r=await api('/api/admin/broadcast',{method:'POST',body:JSON.stringify({kind:document.getElementById('bcKind').value,text})});toastMsg(`Отправлено: ${r.sent} из ${r.total}`);adminBack()}catch(e){toastMsg(e.message)}}

function go(p){state.page=p;state.discipline=null;render()}
document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));document.getElementById('refreshBtn').onclick=()=>render();
(async()=>{try{if(!initData)throw new Error('Откройте дневник через Telegram Mini App.');state.me=await api('/api/me');state.admin=!!state.me.is_admin;if(!state.admin && state.page==='admin')state.page='home';if(!state.admin && state.me.needs_setup){state.setup=true;state.page='settings'}render()}catch(e){content.innerHTML=`<div class="card"><h2>Электронный дневник</h2><p>${esc(e.message)}</p><p class="muted">Откройте Mini App из кнопки в Telegram-боте.</p></div>`}})();
